package io.knowledgebrain.planning;
import java.util.*;import java.time.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.postgresql.ds.PGSimpleDataSource;import org.springframework.jdbc.core.JdbcTemplate;import org.flywaydb.core.Flyway;import org.springframework.mock.web.MockHttpServletRequest;import org.springframework.web.server.ResponseStatusException;import io.micrometer.core.instrument.simple.SimpleMeterRegistry;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_PLANNING_DATABASE_URL",matches=".+")
class ActivityExportIntegrationTest {
 PGSimpleDataSource ds;JdbcTemplate sql;ScheduleStore store;TaskStore tasks;String schema;final UuidV7 ids=new UuidV7(Clock.systemUTC());UUID space,actor;final String trace="b".repeat(32);
 @BeforeEach void init(){ds=new PGSimpleDataSource();ds.setURL(System.getenv("BRAIN_TEST_PLANNING_DATABASE_URL"));ds.setUser("brain_planning");ds.setPassword(System.getenv("BRAIN_TEST_PLANNING_DATABASE_PASSWORD"));schema="schedule_test_"+UUID.randomUUID().toString().replace("-","");new JdbcTemplate(ds).execute("CREATE SCHEMA "+schema);ds.setCurrentSchema(schema);Flyway.configure().dataSource(ds).locations("classpath:db/migration").load().migrate();sql=new JdbcTemplate(ds);store=new ScheduleStore(ds,Clock.systemUTC());tasks=new TaskStore(ds,Clock.systemUTC());space=ids.next();actor=ids.next();}
 @AfterEach void cleanup(){sql.execute("DROP SCHEMA "+schema+" CASCADE");}
 String key(){return UUID.randomUUID().toString().replace("-","");}

 ActivityExportController api(){return new ActivityExportController(ds,"a".repeat(43),new SimpleMeterRegistry());}
 MockHttpServletRequest request(){var r=new MockHttpServletRequest("GET","/internal/planning/activity-events");r.setSecure(true);r.addHeader("Authorization","Bearer "+"a".repeat(43));return r;}
 @Test void fixedHighWatermarkPagesRetainAllThreeKindsAndArchivedSnapshots()throws Exception{var goals=new GoalStore(ds,Clock.systemUTC());for(int i=0;i<2;i++){goals.create(space,actor,key(),new GoalStore.Input("Goal","","NOT_STARTED",null),trace);tasks.create(space,actor,key(),new TaskStore.Input("Task","","COMPLETED","2028-11-05",null),trace);var s=store.create(space,actor,key(),new ScheduleStore.Input("Schedule","","2028-11-05T05:30:00Z","2028-11-05T06:30:00Z","America/New_York",null),trace).schedule();store.change(space,s.scheduleId(),actor,1,null,true,trace);}var api=api();var first=api.page(null,null,request()).getBody();assertEquals(5,first.items().size());assertNotNull(first.nextAfter());var watermark=first.through();var later=goals.create(space,actor,key(),new GoalStore.Input("Later","","NOT_STARTED",null),trace);var rows=new ArrayList<ActivityExportController.Item>();UUID after=null;do{var p=api.page(after,watermark,request()).getBody();assertEquals(watermark,p.through());rows.addAll(p.items());after=p.nextAfter();assertTrue(rows.size()<20);}while(after!=null);assertEquals(8,rows.size());assertEquals(Set.of("planning.goal.v1","planning.task.v1","planning.schedule.v1"),new HashSet<>(rows.stream().map(ActivityExportController.Item::topic).toList()));int retired=0;for(var row:rows){var env=io.knowledgebrain.contracts.planning.goal.v1.GoalEventEnvelopeV1.parseFrom(Base64.getDecoder().decode(row.payload()));assertEquals(row.eventId().toString(),env.getEventId());assertFalse(env.getAggregateId().equals(later.goal().goalId().toString()));if(env.getEventType().equals("ScheduleRetired"))retired++;}assertEquals(2,retired);assertEquals("no-store",api.page(null,watermark,request()).getHeaders().getCacheControl());}
 @Test void onlyScopedHttpsReadCapabilityCanExportOwnRetainedEvents(){var api=api();assertNull(api.page(null,null,request()).getBody().through());for(String header:List.of("Cookie","Authorization","Transfer-Encoding")){var req=request();if(header.equals("Authorization"))req.addHeader(header,"Bearer "+"b".repeat(43));else req.addHeader(header,header.equals("Cookie")?"__Host-brain_guest=browser":"chunked");assertThrows(ResponseStatusException.class,()->api.page(null,null,req));}var no=request();no.removeHeader("Authorization");assertThrows(ResponseStatusException.class,()->api.page(null,null,no));var plain=request();plain.setSecure(false);assertThrows(ResponseStatusException.class,()->api.page(null,null,plain));var unknown=request();unknown.addParameter("spaceId",space.toString());assertThrows(ResponseStatusException.class,()->api.page(null,null,unknown));var duplicate=request();duplicate.addParameter("through",space.toString(),space.toString());assertThrows(ResponseStatusException.class,()->api.page(null,null,duplicate));assertThrows(ResponseStatusException.class,()->api.page(UUID.randomUUID(),null,request()));}
}
